# ⭐ 补丁7 的 OLD/NEW 素材（2026-10-25 按 2.0.4 的 mcp_server.py 重新生成）
#   OLD = 2.0.4 原版 bili_send_message 整块；NEW = 切条版（含 _split_dm_text 与常量）
#   ⚠️ 上游再改这个函数，这里就要重新生成一次（patch-plugin.sh 会报"结构不认识了"）

OLD = '@tool()\nasync def bili_send_message(receiver_uid: int, text: str) -> str:\n    """\n    给B站用户发送私信\n\n    Args:\n        receiver_uid: 接收者的UID\n        text: 私信文本内容\n\n    Returns:\n        发送结果\n    """\n    _deny = _guard("bili_send_message")\n    if _deny: return _deny\n    cred = get_cred()\n\n    if not text or not text.strip():\n        return json.dumps({"success": False, "error": "text 不能为空"}, ensure_ascii=False)\n\n    try:\n        result = await session.send_msg(\n            credential=cred,\n            receiver_id=receiver_uid,\n            msg_type=session.EventType.TEXT,\n            content=text.strip(),\n        )\n        # ⭐ 2.0.4（issue #35）：**接口没抛异常 ≠ 真的送到了** ——\n        #    以前只要不抛就报 success: True，而 B站 可能出现 code=0 却没给投递回执（msg_key）的情况 ✗\n        #    回执就在返回值里：有 msg_key 才算发出去；code 非 0 直接算失败 ✓\n        data = result if isinstance(result, dict) else {}\n        code = data.get("code", 0)\n        inner = data.get("data")\n        msg_key = data.get("msg_key") or (inner.get("msg_key") if isinstance(inner, dict) else None)\n        if code not in (0, None):\n            return json.dumps({\n                "success": False,\n                "error": f"接口拒绝（code={code}）：{data.get(\'message\') or data.get(\'msg\') or \'未知原因\'}",\n                "data": data,\n            }, ensure_ascii=False)\n        if not msg_key:\n            return json.dumps({\n                "success": False,\n                "error": "接口回了成功，但**没有投递回执（msg_key）** ⇒ 可能没真正送到（常见于：对方不接受陌生人私信 / 被风控）",\n                "data": data,\n            }, ensure_ascii=False)\n        return json.dumps({\n            "success": True,\n            "message": f"私信已投递（回执 {str(msg_key)[:12]}…）",\n            "data": data,\n        }, ensure_ascii=False)\n    except Exception as e:\n        return json.dumps({"success": False, "error": str(e)}, ensure_ascii=False)'

NEW = '# ⭐ 本地补丁（2026-10-23 立，2026-10-25 适配 2.0.4）：**发送层负责切条**。\n#   用户要求：模型正常回（不限字数、也不自己分条），由这里按 ~100 字切成几条连着发。\n#   为什么放发送层：模型自己分条会双重切（她分一次、脚本再切一次）✗；字数限制删掉后\n#   长文本必须有人管，否则撞 B站 单条 500 字硬限报 code 21007。\nDM_CHUNK_CHARS = int(os.environ.get("BILI_DM_CHUNK_CHARS", "100") or 100)\nDM_MAX_CHARS = 500      # B站 平台单条硬上限\nDM_GAP_SECONDS = 0.8    # 两条之间喘口气，别撞频率限制\n_SENT_END = "。！？!?…；;\\n"          # 句末标点：优先在这些地方断\n_SOFT_END = "，、, \u3000）)"              # 次级断点：句太长时退到这里\n\n\ndef _split_dm_text(text: str, limit: int = None) -> list:\n    """把一段话切成若干条私信：优先句末标点，其次逗号/空格，最后硬切。\n\n    只做切分、不发送 —— 单独拆出来是为了能单元测试（不真的发私信）。\n    """\n    limit = DM_CHUNK_CHARS if limit is None else limit\n    t = (text or "").strip()\n    if not t:\n        return []\n    if limit <= 0 or len(t) <= limit:\n        return [t]\n    # ① 先切成"句子"\n    pieces, cur = [], ""\n    for ch in t:\n        cur += ch\n        if ch in _SENT_END:\n            pieces.append(cur)\n            cur = ""\n    if cur:\n        pieces.append(cur)\n    # ② 再按上限把句子攒成条\n    chunks, buf = [], ""\n    for p in pieces:\n        if len(buf) + len(p) <= limit:\n            buf += p\n            continue\n        if buf:\n            chunks.append(buf)\n            buf = ""\n        while len(p) > limit:            # 单句就超长 → 退到次级断点，再硬切\n            win = p[:limit]\n            cut = -1\n            for mark in _SOFT_END:\n                cut = max(cut, win.rfind(mark))\n            if cut < limit // 2:\n                cut = limit - 1\n            chunks.append(p[:cut + 1].strip())\n            p = p[cut + 1:].lstrip()\n        buf = p\n    if buf:\n        chunks.append(buf)\n    return [c for c in (x.strip() for x in chunks) if c]\n\n\n@tool()\nasync def bili_send_message(receiver_uid: int, text: str) -> str:\n    """\n    给B站用户发送私信\n\n    ⭐ 长度随意：**不用自己分条**，这里会自动按 ~100 字切成几条连着发\n    （单条上限 500 字是 B站 硬限制，超了报 code 21007，切条时已保证）。\n\n    Args:\n        receiver_uid: 接收者的UID\n        text: 私信文本内容（想写多少写多少）\n\n    Returns:\n        发送结果（含 parts_total / parts_sent / 每条字数与回执）\n    """\n    _deny = _guard("bili_send_message")\n    if _deny: return _deny\n    cred = get_cred()\n\n    if not text or not text.strip():\n        return json.dumps({"success": False, "error": "text 不能为空"}, ensure_ascii=False)\n\n    parts = _split_dm_text(text.strip())\n    sent, last_data = [], None\n    for i, part in enumerate(parts, 1):\n        try:\n            result = await session.send_msg(\n                credential=cred,\n                receiver_id=receiver_uid,\n                msg_type=session.EventType.TEXT,\n                content=part,\n            )\n            # ⭐ 2.0.4（issue #35）：接口没抛异常 ≠ 真送到了 —— 有 msg_key 才算发出去\n            data = result if isinstance(result, dict) else {}\n            last_data = data\n            code = data.get("code", 0)\n            inner = data.get("data")\n            msg_key = data.get("msg_key") or (inner.get("msg_key") if isinstance(inner, dict) else None)\n            if code not in (0, None):\n                return json.dumps({"success": False, "parts_total": len(parts), "parts_sent": len(sent),\n                                   "sent": sent,\n                                   "error": f"第 {i}/{len(parts)} 条被接口拒绝（code={code}）：{data.get(\'message\') or data.get(\'msg\') or \'未知原因\'}"},\n                                  ensure_ascii=False)\n            if not msg_key:\n                return json.dumps({"success": False, "parts_total": len(parts), "parts_sent": len(sent),\n                                   "sent": sent,\n                                   "error": f"第 {i}/{len(parts)} 条没有投递回执（msg_key）⇒ 可能没真送到（对方不收陌生人私信 / 被风控）"},\n                                  ensure_ascii=False)\n            sent.append({"i": i, "chars": len(part), "msg_key": str(msg_key)})\n        except Exception as e:\n            return json.dumps({"success": False, "parts_total": len(parts), "parts_sent": len(sent),\n                               "sent": sent, "error": f"第 {i}/{len(parts)} 条发送异常：{e}"}, ensure_ascii=False)\n        if i < len(parts):\n            await asyncio.sleep(DM_GAP_SECONDS)\n    return json.dumps({\n        "success": True,\n        "parts_total": len(parts),\n        "parts_sent": len(sent),\n        "sent": sent,\n        "message": f"私信已投递：{len(sent)} 条（原文本 {len(text.strip())} 字）",\n        "data": last_data,\n    }, ensure_ascii=False)'
